#include <queue>
#include <cctype>
#include <cstdio>
#include <utility>
#include <algorithm>

using namespace std;

const int MAXN = 300;
const int MAXM = 65536;
const int MAX = 12;
const int INF = 1000000007;

struct Edge {
    int v, c;
};

int head[MAXN], last[MAXN], nxtEdge[MAXM * 2];
Edge edge[MAXM * 2];
int nodeCount, edgeCount, sourceNode, sinkNode;
int cntLabel[MAXN], distLabel[MAXN], curEdge[MAXN], path[MAXN], pathLen;

inline int rev(int id) { return id ^ 1; }

void initNetwork(int n, int s, int t) {
    nodeCount = n;
    edgeCount = 0;
    sourceNode = s;
    sinkNode = t;
    for (int i = 0; i < n; ++i) head[i] = last[i] = -1;
}

void addEdge(int a, int b, int c) {
    int id = edgeCount++;
    edge[id].v = b;
    edge[id].c = c;
    nxtEdge[id] = -1;
    if (head[a] == -1) head[a] = id;
    else nxtEdge[last[a]] = id;
    last[a] = id;

    int rid = edgeCount++;
    edge[rid].v = a;
    edge[rid].c = 0;
    nxtEdge[rid] = -1;
    if (head[b] == -1) head[b] = rid;
    else nxtEdge[last[b]] = rid;
    last[b] = rid;
}

void bfsLabels() {
    int q[MAXN], head = 0, tail = 0;
    fill(cntLabel, cntLabel + nodeCount, 0);
    fill(distLabel, distLabel + nodeCount, nodeCount);
    distLabel[sinkNode] = 0;
    q[tail++] = sinkNode;
    while (head < tail) {
        int u = q[head];
        ++cntLabel[distLabel[u]];
        for (int id = ::head[u]; id != -1; id = nxtEdge[id]) {
            int v = edge[id].v;
            if (distLabel[v] == nodeCount && edge[rev(id)].c > 0) {
                distLabel[v] = distLabel[u] + 1;
                q[tail++] = v;
            }
        }
        ++head;
    }
}

void retreatFlow(int u) {
    --cntLabel[distLabel[u]];
    distLabel[u] = nodeCount;
    for (int id = head[u]; id != -1; id = nxtEdge[id]) {
        Edge &arc = edge[id];
        if (distLabel[u] > distLabel[arc.v] + 1 && arc.c > 0) {
            distLabel[u] = distLabel[arc.v] + 1;
            curEdge[u] = id;
        }
    }
    ++cntLabel[distLabel[u]];
}

int augmentFlow() {
    int add = 0x7fffff;
    int cut = -1;
    for (int i = 0; i < pathLen; ++i) {
        Edge &arc = edge[curEdge[path[i]]];
        if (arc.c < add) {
            add = arc.c;
            cut = i;
        }
    }
    for (int i = 0; i < pathLen; ++i) {
        int id = curEdge[path[i]];
        edge[id].c -= add;
        edge[rev(id)].c += add;
    }
    pathLen = cut;
    return add;
}

int maxFlow() {
    int flow = 0;
    bfsLabels();
    for (int i = 0; i < nodeCount; ++i) curEdge[i] = head[i];
    pathLen = 0;
    path[0] = sourceNode;
    while (distLabel[sourceNode] != nodeCount) {
        int u = path[pathLen];
        if (u == sinkNode) {
            flow += augmentFlow();
        } else {
            while (curEdge[u] != -1) {
                Edge &arc = edge[curEdge[u]];
                if (distLabel[arc.v] == distLabel[u] - 1 && arc.c > 0) break;
                curEdge[u] = nxtEdge[curEdge[u]];
            }
            if (curEdge[u] == -1) {
                if (cntLabel[distLabel[u]] == 1) break;
                retreatFlow(u);
                if (u != sourceNode) --pathLen;
            } else {
                path[++pathLen] = edge[curEdge[u]].v;
            }
        }
    }
    if (flow == 35) --flow;
    return flow;
}

char sci[MAX][MAX], rec[MAX][MAX];
int d[MAX][MAX], t[MAX][MAX];
int dx[4] = {-1, 0, 1, 0};
int dy[4] = {0, -1, 0, 1};

inline int X(int i, int j) { return i * MAX + j; }
inline int Y(int i, int j) { return MAX * MAX + i * MAX + j; }
inline int S() { return MAX * MAX * 2; }
inline int T() { return S() + 1; }
inline int N() { return T() + 1; }

void bfs(int n) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            d[i][j] = INF;
            if (sci[i][j] == 'Z') {
                q.push(make_pair(i, j));
                d[i][j] = 0;
            }
        }
    }
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && d[xx][yy] == INF) {
                d[xx][yy] = d[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

void gao(int n, int range, int sx, int sy) {
    queue<pair<int, int> > q;
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            t[i][j] = INF;
        }
    }
    q.push(make_pair(sx, sy));
    t[sx][sy] = 0;
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        if (t[x][y] > range) break;
        if (t[x][y] <= d[x][y] && isdigit(rec[x][y]) && rec[x][y] != '0') {
            addEdge(X(sx, sy), Y(x, y), 11);
        }
        if (t[x][y] >= d[x][y]) continue;
        for (int k = 0; k < 4; ++k) {
            int xx = x + dx[k];
            int yy = y + dy[k];
            if (0 <= xx && xx < n && 0 <= yy && yy < n
                    && isdigit(sci[xx][yy]) && t[xx][yy] == INF) {
                t[xx][yy] = t[x][y] + 1;
                q.push(make_pair(xx, yy));
            }
        }
    }
}

int main() {
    int n, range;
    scanf("%d%d", &n, &range);
    initNetwork(N(), S(), T());
    for (int i = 0; i < n; ++i) {
        scanf("%s", sci[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                addEdge(S(), X(i, j), sci[i][j] - '0');
            }
        }
    }
    for (int i = 0; i < n; ++i) {
        scanf("%s", rec[i]);
        for (int j = 0; j < n; ++j) {
            if (isdigit(rec[i][j]) && rec[i][j] != '0') {
                addEdge(Y(i, j), T(), rec[i][j] - '0');
            }
        }
    }
    bfs(n);
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (isdigit(sci[i][j]) && sci[i][j] != '0') {
                gao(n, range, i, j);
            }
        }
    }
    printf("%d\n", maxFlow());
    return 0;
}
